import{_ as o,o as u,c as q,ag as e}from"./chunks/framework.CAXxHpAX.js";const l=JSON.parse('{"title":"金刚经3分-四相与无我","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/金刚经3分-四相与无我.md","filePath":"60-原文段落/金刚经3分-四相与无我.md","lastUpdated":1778155802000}'),a={name:"60-原文段落/金刚经3分-四相与无我.md"};function r(p,t,_,s,n,c){return u(),q("div",null,[...t[0]||(t[0]=[e('<h1 id="金刚经3分-四相与无我" tabindex="-1">金刚经3分-四相与无我 <a class="header-anchor" href="#金刚经3分-四相与无我" aria-label="Permalink to &quot;金刚经3分-四相与无我&quot;">​</a></h1><blockquote><p>来源：<a href="/01-Raw-Sources/3了空居士讲《金刚经》-第三分大乘正宗分20160916">3了空居士讲《金刚经》-第三分大乘正宗分20160916</a> 切分日期：2026-05-06</p></blockquote><hr><p><strong>若菩萨有我相、人相、众生相、寿者相，即非菩萨。</strong></p><p>假如你是一位发愿行菩萨道的行者，你就不应该有这种&quot;我相人相众生相寿者相&quot;，也就是说，对自己也不要有这种事相的执着，对周边的一切众生也不要有这种事相的执着。你天天做事，但是你不要认为你功劳很大嘛，你天天在度众生，你要认为这是正常的事情啊，而不是说我... 你不管度多少众生，严格来说，你本来就是发愿要将所有众生都度完的，你就不能老是觉得&quot;唉呀，我今天也干得不错啦，今天也度了很多人了&quot;。如果有这样，你永远没办法进入圆满的境界，你要达到度众生就是一种常态，一种我的分内之事，没有什么功德相，达到这个状态的人，你才符合这个菩萨的标准，做菩萨就是不能有功德相，你要帮助别人，就像帮助自己一样，很自然地去做，达到这个心态，你才是大乘的境界，&quot;大乘正宗&quot;的境界。</p><p>如果你帮助别人，觉得&quot;唉呀，我做的有点厌倦啦&quot;，或者是&quot;我做得自我感觉良好了&quot;，都不对！你要发自内心觉得帮助众生是你的正常的行为，就像帮助自己一样。好像我们的手，每天要做什么事情，你就不用说：&quot;唉呀，我的手怎么这么累啊&quot;，你的脚需要怎么走路就怎么走路，一切都是那么的自然，达到这样，就是&quot;无我相无人相无众生相无寿者相&quot;。好像我们没有手足的相，没有说&quot;唉呀，今天走路走得多，我的脚会这么累啊，我的手为什么不下来帮啊&quot;，我今天的手做了很多事，也不会指责我的脚怎么不起来帮助手做点事，不会有这个感觉，也就是&quot;不二&quot;的境界。</p><hr><p><strong>如是灭度无量无数无边众生，实无众生得灭度者。</strong></p><p>我告诉你明树，就像我们打一个不怎么恰当的比喻啊，我了空居士在网络上和现实中也帮助了很多人，但是我从来的心清清净净的，不觉得&quot;唉呀，我帮助了别人，人家怎么有什么感谢我啊，没有啊&quot;，我不想的，我认为这个是我自然的流露嘛。</p><p>我心里没有觉得帮助和不帮助，&quot;实无众生得灭度者&quot;这句话是省略句，就是说我不会执着众生到底多少个人已经成就了，因为我生生世世都必须这么做，是这个意思。因为古人是他当时能听清楚，所以他就不用特别去注解。&quot;实无众生得灭度者&quot;，就是说我心里不觉得他们已经因为我而成就，而是我觉得需要这么做。像明树，你们养小孩，你们不会天天看着小孩，&quot;今天又长大了一点了&quot;，&quot;唉，明天要长大一点&quot;没有吧，是不是，明树？我跟你说你就知道了吧，哈哈，就好像培养小孩一样嘛。你们好像每天都对自己的儿女很好很关心，但是你不觉得你很关心他，你觉得是自然的，就是父母的责任啊，是不是啊？就是这个心态。</p><hr><p><strong>知见无见，斯即涅槃，无漏真净。</strong></p><p>我们自己要入无余涅槃，其实很简单，就是&quot;知见无见&quot;啦，不要带着任何成见去看问题和看自己啊，这就是六祖对惠明说&quot;不思善不思恶，返照汝边&quot;啊。你们明白了，你们现在就是&quot;无余涅槃&quot;了，是不是啊？</p><p>那你们要大彻大悟太简单了，不要带着任何成见，&quot;以无我无人无众生无寿者修一切善法&quot;，你们就达到了这个标准了。那你说那这样我就跟诸佛一样了？不是，你们要历境炼心，要处处能够使你都能够达到这个标准，那你就大彻大悟啦，跟诸佛如来一致啦，是不是啊？</p><p>其实就是很多人就老是在&quot;我要什么时候能开悟？&quot;你不知道开悟的人和不开悟的人有什么区别。开悟的人就能够&quot;以无我无人无众生无寿者修一切善法&quot;，不开悟的人就是老是在搞&quot;贪嗔痴&quot;嘛，哈哈，就这么简单嘛。那么你永远保持&quot;无我无人无众生无寿者修一切善法&quot;，一切时一切处你都能够标准的这么做，你就大彻大悟啦。</p>',15)])])}const i=o(a,[["render",r]]);export{l as __pageData,i as default};
